import re
from pathlib import Path
brief = Path('projects/scale_seal_deck_ppt169_20260421/sources/source_brief.md').read_text()
lab_by_model = {
 'GPT': 'OpenAI',
 'o3': 'OpenAI',
 'Claude': 'Anthropic',
 'Gemini': 'Google',
 'Muse Spark': 'Muse Spark',
}

def lab_for(model):
 for k,v in lab_by_model.items():
  if k in model:
   return v
 return 'Other'

def parse_md_table(text):
 lines=[l.rstrip() for l in text.splitlines()]
 start=None
 for idx,l in enumerate(lines):
  if l.strip().startswith('|') and idx+1<len(lines) and set(lines[idx+1].strip())<=set('|- :') and '|' in lines[idx+1]:
   start=idx
   break
 if start is None:
  return []
 header=[c.strip() for c in lines[start].strip().strip('|').split('|')]
 rows=[]
 for l in lines[start+2:]:
  if not l.strip().startswith('|'):
   break
  cells=[c.strip() for c in l.strip().strip('|').split('|')]
  if len(cells)!=len(header):
   continue
  rows.append(dict(zip(header,cells)))
 return rows

agentic = re.search(r"## Agentic Coding Benchmarks(.*?)## Frontier", brief, re.S).group(1)
frontier = re.search(r"## Frontier Reasoning.*?(.*?)## Multimodal", brief, re.S).group(1)
safety = re.search(r"## Safety & Alignment Benchmarks(.*?)(## Key Findings|$)", brief, re.S).group(1)

agentic_rows=parse_md_table(agentic)
frontier_rows=parse_md_table(frontier)
safety_rows=parse_md_table(safety)

winners=[]
for r in agentic_rows:
 winners.append((r['Benchmark'], r['#1 Model'], lab_for(r['#1 Model']), r['Score']))
for r in frontier_rows:
 winners.append((r['Benchmark'], r['#1 Model'], lab_for(r['#1 Model']), r['Score']))
winners += [
 ('AudioMultiChallenge (Text Output)', 'Gemini-3-pro-preview', 'Google', '54.65 ±4.57'),
 ('AudioMultiChallenge (Audio Output)', 'Gemini-3.1-flash-live-preview', 'Google', '36.06 ±4.41'),
 ('VISTA (Vision-Language)', 'Gemini 2.5 Pro Experimental', 'Google', '54.65 ±1.46'),
 ('VisualToolBench', 'GPT-5.4', 'OpenAI', '29.17')
]
for r in safety_rows:
 if r['#1 Model'].strip()=='—':
  continue
 winners.append((r['Benchmark'], r['#1 Model'], lab_for(r['#1 Model']), r['Score']))

print('Winners count:', len(winners))
for b,m,lab,s in winners:
 print(f"- {b}: {m} ({lab}) {s}")
PY

